mapper.select:
SELECT user_id, friend_id, status, remark, created_at, updated_at
FROM im_friend
WHERE user_id = #{userId} AND friend_id = #{friendId}

mapper.update:
UPDATE im_friend
SET status = #{status},
    updated_at = NOW()
WHERE user_id = #{userId}
  AND friend_id = #{friendId}

mapper.delete:
DELETE FROM im_friend
WHERE user_id = #{userId}
  AND friend_id = #{friendId}
